import { createTRPCClient, localLink, TRPCClientError } from '@trpc/client';
import { initTRPC, TRPCError } from '@trpc/server';
import { tracked } from '@trpc/server/unstable-core-do-not-import';
import { z } from 'zod';
import { EventEmitter, on } from 'node:events';

test('localLink with tracked subscription', async () => {
  const ee = new EventEmitter();
  const t = initTRPC.create();

  const router = t.router({
    onMessage: t.procedure
      .subscription(async function* () {
        let i = 0;
        for await (const [msg] of on(ee, 'message')) {
          yield tracked(String(++i), msg);
        }
      }),
  });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router })],
  });

  const received: any[] = [];
  const sub = client.onMessage.subscribe(undefined, {
    onData(data) {
      received.push(data);
    },
  });

  ee.emit('message', 'first');

  await vi.waitFor(() => {
    expect(received).toHaveLength(1);
  });

  expect(received[0]).toMatchObject({
    id: '1',
    data: {
      id: '1',
      data: 'first',
    },
  });

  sub.unsubscribe();
});

