import { jsonlStreamConsumer, jsonlStreamProducer } from './jsonl';
import { createDeferred } from './utils/createDeferred';

test('jsonlStreamConsumer should not abort until all parts are finished', async () => {
  const deferred = createDeferred<string>();

  const data = {
    iterable: Promise.resolve({
      [Symbol.asyncIterator]: async function* () {
        yield 1;
      },
    }),
    late: deferred.promise,
  } as const;

  const producerStream = jsonlStreamProducer({
    data,
    serialize: (v) => v,
  });

  const abortController = new AbortController();
  const [head, meta] = await jsonlStreamConsumer<typeof data>({
    from: producerStream,
    deserialize: (v) => v,
    abortController,
  });

  // 1. Consume the iterable completely
  const iterable = await head.iterable;
  for await (const _ of iterable) {
    // just consume
  }

  // 2. The iterable is finished. isEmpty() might return true now if it doesn't account for the main stream.

  // 3. Resolve the late promise
  deferred.resolve('finally');

  // 4. Check if the late promise resolves correctly
  await expect(head.late).resolves.toBe('finally');

  expect(abortController.signal.aborted).toBe(false);
});

