      if (state !== 'idle') {
        throw new Error('Cannot iterate twice');
      }
      state = 'pending';

      const _finally = makeAsyncResource({}, async () => {
        state = 'done';

        const errors: unknown[] = [];
        await Promise.all(
          Array.from(iterators.values()).map(async (it) => {
            try {
              await it.destroy();
            } catch (cause) {
              errors.push(cause);
            }
          }),
        );
        buffer.length = 0;
        iterators.clear();
        flushSignal.resolve();

        if (errors.length > 0) {
          throw new AggregateError(errors);
        }
